import assert from "node:assert/strict";
import { spawn } from "node:child_process";
import { createServer, createConnection } from "node:net";
import { once } from "node:events";
const reservation = createServer();
reservation.listen(0, "127.0.0.1");
await once(reservation, "listening");
const port = reservation.address().port;
await new Promise((resolve) => reservation.close(resolve));
const server = spawn(process.execPath, ["docs/design/2026-10-12-code-wiki/serve.mjs"], { env: { ...process.env, WIKI_PORT: String(port) }, stdio: ["ignore", "pipe", "pipe"] });
server.stderr.on("data", (data) => process.stderr.write(data));
const exited = once(server, "exit");
const request = async (target, method = "GET") => {
  const socket = createConnection({ host: "127.0.0.1", port });
  let response = "";
  socket.setEncoding("utf8");
  socket.setTimeout(5000, () => socket.destroy(new Error("request timeout")));
  socket.on("data", (data) => { response += data; });
  socket.on("error", () => {});
  await once(socket, "connect");
  socket.write(`${method} ${target} HTTP/1.1\r\nHost: localhost\r\nConnection: close\r\n\r\n`);
  await once(socket, "close");
  return response;
};
try {
  await Promise.race([once(server.stdout, "data"), exited.then(() => { throw new Error("server exited before readiness"); })]);
  for (const [target, method, status] of [["/", "GET", 200], ["/app.js", "GET", 200], ["/sources.js", "HEAD", 200], ["/package.json", "GET", 404], ["/../../package.json", "GET", 404], ["/%2e%2e/%2e%2e/package.json", "GET", 404], ["/", "POST", 404], ["http://[", "GET", 400]]) {
    const response = await request(target, method);
    assert.match(response, new RegExp(`^HTTP/1.1 ${status} `));
    if (method === "HEAD") assert.equal(response.split("\r\n\r\n")[1], "");
    console.log(method, target, status);
  }
  assert.equal((await fetch(`http://127.0.0.1:${port}/`)).status, 200);
  console.log("Preview remains available after rejected requests.");
} finally {
  if (server.exitCode === null && server.signalCode === null) server.kill("SIGTERM");
  await exited;
}
